package com.bare.folders.task; public final class FolderBackupResult { public enum Kind{FAILURE,NO_CHANGE,SUCCESS} private final Kind kind; private final long bytes,durationMs; public FolderBackupResult(Kind kind,long bytes,long durationMs){if(kind==null)throw new IllegalArgumentException("kind");this.kind=kind;this.bytes=Math.max(0,bytes);this.durationMs=Math.max(0,durationMs);} public Kind getKind(){return kind;} public long getBytes(){return bytes;} public long getDurationMs(){return durationMs;} }